/* Case-insensitive name lookup. Returns id or -1 if not found. */
static int
GMNameEntry_Lookup(const GMNameEntry *table, int count, const char *name)
{
	int i;
	for (i = 0; i < count; i++) {
		if (strcasecmp(table[i].name, name) == 0)
			return table[i].id;
	}
	// Partial prefix match (minimum 3 chars)
	int len = (int)strlen(name);
	if (len >= 3) {
		for (i = 0; i < count; i++) {
			if (strncasecmp(table[i].name, name, len) == 0)
				return table[i].id;
		}
	}
	return -1;
}

/* Reverse lookup: id -> name. Returns name or NULL. */
static const char *
GMNameEntry_ReverseLookup(const GMNameEntry *table, int count, int id)
{
	int i;
	for (i = 0; i < count; i++) {
		if (table[i].id == id)
			return table[i].name;
	}
	return NULL;
}

